-- Elaria Hyprland binds — LUA config syntax. This is the FIRST-Choice format:
-- Hyprland 0.55+ reads it, and 0.57 reads ONLY this (the legacy bind/bindr
-- format was deleted upstream). Generated by `assistant.hypr_binds.emit_binds`
-- — pinned byte-for-byte by tests/test_task_m_followup.py, so edit the emitter,
-- not this file.
--
-- Push-to-talk = press starts, release stops (Step 6 of GETTING-STARTED).
-- The release bind carries `ignore_mods = true` (the Lua form of the `bindri`
-- flag): the stop fires on key release whichever modifiers are still held.
-- Without it the stop only fires in one release order and a Win-first release
-- leaks the mic (scene 3b, 2026-10-26, hardware).
--
-- `Escape` cancels the session in flight (F30): the partial buffer is zeroized
-- and the capture node released — a cancel is a stop with destruction.

hl.bind("SUPER + grave", hl.dsp.exec_cmd("assist ptt start"))
hl.bind("SUPER + grave", hl.dsp.exec_cmd("assist ptt stop --stop-source bind"), { release = true, ignore_mods = true })
hl.bind("Escape", hl.dsp.exec_cmd("assist ptt cancel"))
hl.bind("SUPER + SHIFT + F12", hl.dsp.exec_cmd("assist halt"))
